8	/// The entries feature's one write call so far (`entries-create`) — posts
9	/// via the shared `ApiClient`, mirroring `account_remote_data_source.dart`'s
10	/// pattern.
11	class EntriesRemoteDataSource {
12	  EntriesRemoteDataSource(this._apiClient);
13	
14	  final ApiClient _apiClient;
15	
16	  /// Sends `{content, source}` plus `mediaDurationSeconds` only when
17	  /// non-null (spec-3-2's `source: audio` entries) — this story still
18	  /// never passes `chatMessageId`/`occurredAt` (Boundaries: no `Entry`
19	  /// field beyond the modeled 9; those two are optional in the contract
20	  /// and belong to later stories/epics).
21	  Future<Either<Failure, EntryDto>> create({
22	    required String content,
23	    required EntrySource source,
24	    int? mediaDurationSeconds,
25	  }) async {
26	    final result = await _apiClient.post(
27	      'entries-create',
28	      data: {
29	        'content': content,
30	        'source': source.name,
31	        'mediaDurationSeconds': ?mediaDurationSeconds,
32	      },
33	    );
34	    return result.flatMap((json) {
35	      try {
36	        final data = json['data'] as Map<String, dynamic>;
37	        return right(EntryDto.fromJson(data));
38	      } catch (error) {
39	        // A 200 response that doesn't match the expected shape is a
40	        // client-side parse failure, never a backend-sent code — maps to
41	        // the local-only `malformedResponse` (RNF09: no exception escapes
42	        // unmapped).
43	        return left(Failure.malformedResponse(message: error.toString()));
44	      }
45	    });
46	  }
47	
48	  /// Calls `entries-list` (`ApiClient.get`) with `limit` always sent, and
49	  /// `cursor` only when non-null (spec-4-1's own convention for an
50	  /// optional-in-the-contract query parameter, mirroring [create]'s own
51	  /// `mediaDurationSeconds` handling). Returns the raw page as a record —
52	  /// no dedicated DTO wrapper type, since `EntriesRepositoryImpl.list()` is
53	  /// this record's only reader.
54	  Future<Either<Failure, ({List<EntryDto> items, String? nextCursor})>> list({
55	    String? cursor,
56	    int limit = 20,
57	  }) async {
58	    final result = await _apiClient.get(
59	      'entries-list',
60	      queryParameters: {'limit': limit, 'cursor': ?cursor},
61	    );
62	    return result.flatMap((json) {
63	      try {
64	        final data = json['data'] as List<dynamic>;
65	        final items = data
66	            .map((item) => EntryDto.fromJson(item as Map<String, dynamic>))
67	            .toList();
68	        final meta = json['meta'] as Map<String, dynamic>;
69	        final nextCursor = meta['nextCursor'] as String?;
70	        return right((items: items, nextCursor: nextCursor));
71	      } catch (error) {
72	        // Same client-side-parse-failure rationale as `create()` above.
73	        return left(Failure.malformedResponse(message: error.toString()));
74	      }
75	    });
76	  }
77	
78	  /// Calls `entries-get` (`ApiClient.get`) with [id] appended as the one
79	  /// trailing path segment (Conventions: "path parameters appended as
80	  /// trailing segments") — decodes the response's own `data` object exactly
81	  /// as [create]/[list] already do, a superset [EntryDto] already handles
82	  /// (Boundaries: "its response is a superset, same as create/list's DTO
83	  /// reuse").
84	  Future<Either<Failure, EntryDto>> get(String id) async {
85	    final result = await _apiClient.get('entries-get', pathParams: [id]);
86	    return result.flatMap((json) {
87	      try {
88	        final data = json['data'] as Map<String, dynamic>;
89	        return right(EntryDto.fromJson(data));
90	      } catch (error) {
91	        // Same client-side-parse-failure rationale as `create()`/`list()`
92	        // above.
93	        return left(Failure.malformedResponse(message: error.toString()));
94	      }
95	    });
96	  }
97	
98	  /// spec-5-1 — calls `entries-search` (`ApiClient.get`) with exactly one
99	  /// query parameter, `q` (Boundaries: no `limit`/`cursor`). The response's
100	  /// `data` array decodes with the exact same `EntryDto.fromJson` [list]
101	  /// already uses — a superset response (`similarity`/`mode` fields the
102	  /// Code Map names) is simply ignored by `json_serializable`'s generated
103	  /// `fromJson`, same convention [get]'s own superset-response doc already
104	  /// gives.
105	  Future<Either<Failure, List<EntryDto>>> search(String query) async {
106	    final result = await _apiClient.get(
107	      'entries-search',
108	      queryParameters: {'q': query},
109	    );
110	    return result.flatMap((json) {
111	      try {
112	        final data = json['data'] as List<dynamic>;
113	        final items = data
114	            .map((item) => EntryDto.fromJson(item as Map<String, dynamic>))
115	            .toList();
116	        return right(items);
117	      } catch (error) {
118	        // Same client-side-parse-failure rationale as `create()`/`list()`/
119	        // `get()` above.
120	        return left(Failure.malformedResponse(message: error.toString()));
121	      }
122	    });
123	  }
124	}
