1	// The constructor keeps public named params (`remoteDataSource`,
2	// `entriesBox`) distinct from the private fields they initialize, matching
3	// `account_settings_repository_impl.dart`'s documented convention.
4	// ignore_for_file: prefer_initializing_formals
5	import 'package:fpdart/fpdart.dart';
6	import 'package:hive_ce/hive_ce.dart';
7	
8	import '../../../../core/failure/failure.dart';
9	import '../../../../core/utils/deduped_by_id.dart';
10	import '../../domain/entities/entries_page.dart';
11	import '../../domain/entities/entry.dart';
