16	/// On success, writes the entry through to the `entries` Hive box (`Box
17	/// <Map>`, keyed by id, raw `EntryDto.toJson()` — Design Notes) *before*
18	/// returning `right(...)`, same "persist then return" ordering
19	/// `AuthRepositoryImpl._authenticate` already uses for its own
20	/// post-success side effect.
21	class EntriesRepositoryImpl implements EntriesRepository {
22	  EntriesRepositoryImpl({
23	    required EntriesRemoteDataSource remoteDataSource,
24	    required Box<Map> entriesBox,
25	  }) : _remoteDataSource = remoteDataSource,
26	       _entriesBox = entriesBox;
27	
28	  final EntriesRemoteDataSource _remoteDataSource;
29	  final Box<Map> _entriesBox;
30	
31	  @override
32	  Future<Either<Failure, Entry>> create({
33	    required String content,
34	    required EntrySource source,
35	    int? mediaDurationSeconds,
36	  }) async {
37	    final result = await _remoteDataSource.create(
38	      content: content,
39	      source: source,
40	      mediaDurationSeconds: mediaDurationSeconds,
41	    );
42	    return result.match((failure) async => left(failure), (dto) async {
43	      // A thrown Hive/disk exception must never escape unmapped (RNF09) —
44	      // same rationale/fallback `AuthRepositoryImpl` already uses for its
45	      // own local-persistence step.
46	      try {
47	        await _entriesBox.put(dto.id, dto.toJson());
48	      } catch (error) {
49	        return left(Failure.malformedResponse(message: error.toString()));
50	      }
51	      return right(_toEntry(dto));
52	    });
53	  }
54	
55	  @override
56	  Future<Either<Failure, EntriesPage>> list({
57	    String? cursor,
58	    int limit = 20,
59	  }) async {
60	    final result = await _remoteDataSource.list(cursor: cursor, limit: limit);
61	    return result.match(
62	      (failure) async {
63	        // Boundaries/Design Notes: the Hive-cache fallback is scoped to
64	        // `cursor == null` (the first/fresh page) only — a paginated
65	        // continuation (`cursor != null`) that fails with
66	        // `networkOffline`/`networkTimeout` propagates as `Left` like any
67	        // other pagination failure instead, so `MeusRegistrosCubit`'s own
68	        // `loadMoreFailed`/retry path handles it uniformly rather than a
69	        // full unrelated cache dump silently replacing the in-progress
70	        // paginated list (and breaking its newest-first ordering).
71	        if (cursor == null &&
72	            (failure is NetworkOffline || failure is NetworkTimeout)) {
73	          return _offlineFallback();
74	        }
75	        return left(failure);
76	      },
77	      (page) async {
78	        try {
79	          await _entriesBox.putAll({
80	            for (final dto in page.items) dto.id: dto.toJson(),
81	          });
82	        } catch (error) {
83	          // Same RNF09 rationale as `create()`'s own Hive-write guard — a
84	          // thrown Hive/disk exception must never escape unmapped.
85	          return left(Failure.malformedResponse(message: error.toString()));
86	        }
87	        return right(
88	          EntriesPage(
89	            items: page.items.map(_toEntry).toList(),
90	            nextCursor: page.nextCursor,
91	          ),
92	        );
93	      },
94	    );
95	  }
96	
97	  @override
98	  Future<Either<Failure, Entry>> getById(String id) async {
99	    final result = await _remoteDataSource.get(id);
100	    return result.match(
101	      (failure) async {
102	        // Boundaries: scoped to networkOffline/networkTimeout specifically
103	        // — every other Failure (notFound included) propagates as Left,
104	        // unmapped, same convention `list()`'s own cursor-scoped fallback
105	        // above uses.
106	        if (failure is NetworkOffline || failure is NetworkTimeout) {
107	          return _cachedEntryOrOriginalFailure(id, failure);
108	        }
109	        return left(failure);
110	      },
111	      (dto) async {
112	        // Same RNF09 rationale as `create()`/`list()`'s own Hive-write
113	        // guards — a thrown Hive/disk exception must never escape
114	        // unmapped.
115	        try {
116	          await _entriesBox.put(dto.id, dto.toJson());
117	        } catch (error) {
118	          return left(Failure.malformedResponse(message: error.toString()));
119	        }
120	        return right(_toEntry(dto));
121	      },
122	    );
123	  }
124	
125	  @override
126	  Future<Either<Failure, List<Entry>>> search(String query) async {
127	    final result = await _remoteDataSource.search(query);
128	    return result.match(
129	      (failure) async {
130	        // Boundaries/AD-9: no cache fallback for search, unlike
131	        // list()/getById() — every Failure (including
132	        // networkOffline/networkTimeout) propagates as Left, unmapped.
133	        return left(failure);
134	      },
135	      (dtos) async {
136	        // Review finding: de-duplicated by id first (first-occurrence-wins,
137	        // same semantics as `MeusRegistrosCubit`'s own trust-but-verify
138	        // convention for server data, shared via `core/utils/
139	        // deduped_by_id.dart`) — so the `putAll` below and the returned
140	        // list stay consistent, and `_SearchResults`' `ListView.builder`
141	        // (keyed by `ValueKey(entry.id)`) never sees a duplicate key even
142	        // if the backend ever violated its own no-duplicate-ids invariant.
143	        final dedupedDtos = dedupedById(dtos, (dto) => dto.id);
144	        // Same RNF09 rationale as create()/list()/getById()'s own
145	        // Hive-write guards — a thrown Hive/disk exception must never
146	        // escape unmapped.
147	        try {
148	          await _entriesBox.putAll({
149	            for (final dto in dedupedDtos) dto.id: dto.toJson(),
150	          });
151	        } catch (error) {
152	          return left(Failure.malformedResponse(message: error.toString()));
153	        }
154	        return right(dedupedDtos.map(_toEntry).toList());
155	      },
156	    );
157	  }
158	
159	  /// [getById]'s own offline/timeout fallback (Boundaries): a cache hit
160	  /// returns `Right` from the cached `EntryDto`; a cache miss propagates
161	  /// [originalFailure] unchanged — "no synthesized not-found" — rather than
162	  /// inventing a [Failure.notFound] this repository never actually
163	  /// received from the backend. A corrupt cached entry (should never
164	  /// happen — every entry here was written by [create]/[list]/[getById]
165	  /// themselves) maps to `Left(malformedResponse)` rather than throwing
166	  /// (RNF09), same guard `_offlineFallback()`'s own malformed-cache check
167	  /// uses.
168	  Either<Failure, Entry> _cachedEntryOrOriginalFailure(
169	    String id,
170	    Failure originalFailure,
171	  ) {
172	    try {
173	      final cached = _entriesBox.get(id);
174	      if (cached == null) {
175	        return left(originalFailure);
176	      }
177	      return right(_toEntry(EntryDto.fromJson(Map<String, dynamic>.from(cached))));
178	    } catch (error) {
179	      return left(Failure.malformedResponse(message: error.toString()));
180	    }
181	  }
182	
183	  /// The offline/timeout fallback (Boundaries): a full `entries` Hive box
184	  /// dump, sorted `occurredAt` desc, always `nextCursor: null` — a cached
185	  /// dump has no further page to request. A corrupt cached entry (should
186	  /// never happen — every entry here was written by [create]/[list]
187	  /// themselves) maps to `Left(malformedResponse)` rather than throwing
188	  /// (RNF09), same guard `create()`'s own Hive write already has.
189	  Either<Failure, EntriesPage> _offlineFallback() {
190	    try {
191	      final entries =
192	          _entriesBox.values
193	              .map(
194	                (json) => _toEntry(
195	                  EntryDto.fromJson(Map<String, dynamic>.from(json)),
196	                ),
197	              )
198	              .toList()
199	            ..sort(
200	              (a, b) =>
201	                  DateTime.parse(b.occurredAt)
202	                      .compareTo(DateTime.parse(a.occurredAt)),
203	            );
204	      return right(EntriesPage(items: entries, nextCursor: null));
205	    } catch (error) {
206	      return left(Failure.malformedResponse(message: error.toString()));
207	    }
208	  }
209	
210	  Entry _toEntry(EntryDto dto) => Entry(
211	    id: dto.id,
212	    content: dto.content,
213	    source: dto.source,
214	    chatMessageId: dto.chatMessageId,
215	    occurredAt: dto.occurredAt,
216	    serverRevision: dto.serverRevision,
217	    createdAt: dto.createdAt,
218	    updatedAt: dto.updatedAt,
219	    mediaDurationSeconds: dto.mediaDurationSeconds,
220	  );
221	}
