3	import 'package:flutter_bloc/flutter_bloc.dart';
4	
5	import '../../../../core/utils/deduped_by_id.dart';
6	import '../../domain/entities/entry.dart';
7	import '../../domain/entities/pending_entry_write.dart';
8	import '../../domain/repositories/entries_repository.dart';
9	import '../../domain/services/pending_entry_write_tracker.dart';
10	import 'meus_registros_state.dart';
11	
12	/// Drives `MeusRegistrosScreen` — calls `EntriesRepository.list()` directly
13	/// (no use-case layer, matching this codebase's existing small-scope
14	/// convention: `AccountSettingsCubit`/`AuthCubit`/`TextEntryCubit`). A
15	/// `lazySingleton` (Code Map), like `AccountSettingsCubit` — long-lived, so
16	/// the already-fetched pages survive leaving and re-entering
17	/// `/meus-registros` within the same app session.
18	///
19	/// spec-4-2 — also subscribes to [PendingEntryWriteTracker.pendingWrites]/
20	/// `.confirmedWrites` for this cubit's whole lifetime (constructor-wired,
21	/// not `loadFirstPage()`-wired): both streams are shared singleton
22	/// broadcasts a capture cubit on a *different* screen can drive at any
23	/// time, and this cubit is itself a long-lived singleton that must reflect
24	/// them regardless of which screen is currently visible.
25	class MeusRegistrosCubit extends Cubit<MeusRegistrosState> {
26	  MeusRegistrosCubit(this._repository, this._tracker)
27	    : super(const MeusRegistrosLoading()) {
28	    _pendingSubscription = _tracker.pendingWrites.listen(
29	      _onPendingWritesChanged,
30	    );
31	    _confirmedSubscription = _tracker.confirmedWrites.listen(
32	      _onEntryConfirmed,
33	    );
34	  }
35	
36	  final EntriesRepository _repository;
37	  final PendingEntryWriteTracker _tracker;
38	  late final StreamSubscription<List<PendingEntryWrite>> _pendingSubscription;
39	  late final StreamSubscription<({String tempId, Entry entry})>
40	  _confirmedSubscription;
41	
42	  /// Mirrors the tracker's own latest snapshot regardless of [state]'s
43	  /// current type — so a pending write that arrives while [state] is
44	  /// still [MeusRegistrosLoading]/[MeusRegistrosError] isn't lost: the
45	  /// next [loadFirstPage] that resolves into [MeusRegistrosLoaded]/
46	  /// [MeusRegistrosEmpty] seeds itself from this field directly.
47	  List<PendingEntryWrite> _pendingWrites = const [];
48	
49	  /// A monotonic counter guarding against a stale in-flight call's result
50	  /// landing after a newer call has already changed the state (e.g. the
51	  /// user leaves and quickly re-enters `/meus-registros` while a slow
52	  /// first request is still pending, or taps retry before the original
53	  /// request resolves). Incremented at the start of every [loadFirstPage],
54	  /// then captured locally before each `await` in [loadFirstPage]/
55	  /// [_fetchMore] — a result whose captured generation no longer matches
56	  /// this counter by the time it resolves is discarded rather than
57	  /// emitted.
58	  int _generation = 0;
59	
60	  void _onPendingWritesChanged(List<PendingEntryWrite> pendingWrites) {
61	    _pendingWrites = pendingWrites;
62	    final current = state;
63	    if (current is MeusRegistrosLoaded) {
64	      emit(current.copyWith(pendingWrites: pendingWrites));
65	    } else if ((current is MeusRegistrosEmpty || current is MeusRegistrosError) &&
66	        pendingWrites.isNotEmpty) {
67	      // A capture save starts while this screen is showing "no entries
68	      // yet" or a load failure (Review finding: the latter previously
69	      // fell through this check entirely, silently dropping the pending
70	      // card) — its own placeholder card must still show immediately
71	      // (Acceptance Criteria), not wait for a reload.
72	      emit(
73	        MeusRegistrosLoaded(
74	          entries: const [],
75	          nextCursor: null,
76	          pendingWrites: pendingWrites,
77	        ),
78	      );
79	    }
80	    // MeusRegistrosLoading: nothing to overlay onto yet — [_pendingWrites]
81	    // above already keeps the latest snapshot, which the next
82	    // loadFirstPage() resolution reads directly.
83	  }
84	
85	  void _onEntryConfirmed(({String tempId, Entry entry}) confirmation) {
86	    final entry = confirmation.entry;
87	    // Review finding: drops this write's own pending placeholder from
88	    // this cubit's *local* record synchronously with prepending the
89	    // confirmed entry, in the very same handler — the tracker's own
90	    // `pendingWrites` stream will also eventually deliver the matching
91	    // removal, but that's a separate `Stream.multi`-wrapped subscription
92	    // that can land one microtask late, which previously left a one-frame
93	    // window where both the stale placeholder and the real confirmed
94	    // entry rendered at once.
95	    _pendingWrites = [
96	      for (final pending in _pendingWrites)
97	        if (pending.tempId != confirmation.tempId) pending,
98	    ];
99	    final current = state;
100	    if (current is MeusRegistrosLoaded) {
101	      // Prepended, not reloaded (Design Notes) — preserves this cubit's
102	      // own pagination state (`nextCursor`/`loadMoreFailed`) exactly as
103	      // `loadMore()`'s own cursor-overlap robustness already relies on;
104	      // `dedupedById` (unchanged) absorbs the degenerate case where a
105	      // later `list()`/`loadMore()` page's cursor also happens to repeat
106	      // this same (now server-known) id.
107	      emit(
108	        current.copyWith(
109	          entries: dedupedById([entry, ...current.entries], (e) => e.id),
110	          pendingWrites: _pendingWrites,
111	        ),
112	      );
113	    } else if (current is MeusRegistrosEmpty || current is MeusRegistrosError) {
114	      // Review finding: MeusRegistrosError previously fell through this
115	      // check too, same rationale as `_onPendingWritesChanged` above.
116	      emit(
117	        MeusRegistrosLoaded(
118	          entries: [entry],
119	          nextCursor: null,
120	          pendingWrites: _pendingWrites,
121	        ),
122	      );
123	    }
124	    // MeusRegistrosLoading: the next loadFirstPage() fetches the server's
125	    // own fresh page, which already includes this entry now that it's
126	    // confirmed server-side — nothing to reconcile.
127	  }
128	
129	  /// `EntryRecordCard`'s own retry tap (`MeusRegistrosScreen`) — forwards
130	  /// to the shared tracker verbatim (Never: "a second retry endpoint").
131	  Future<void> retry(String tempId) => _tracker.retry(tempId);
132	
133	  /// `MeusRegistrosScreen.initState` calls this once, every mount — always
134	  /// re-fetches from scratch rather than keeping a previous visit's page
135	  /// around, since a new entry may have been saved (Insertion Modal, Epic
136	  /// 3) since the last visit.
137	  Future<void> loadFirstPage() async {
138	    final generation = ++_generation;
139	    emit(const MeusRegistrosLoading());
140	    final result = await _repository.list();
141	    // Mirrors `AccountSettingsCubit.toggleBiometric`'s own guard: `close()`
142	    // can race this awaited call (e.g. a fast app teardown mid-request) —
143	    // `emit()` after `close()` would otherwise throw.
144	    if (isClosed || generation != _generation) {
145	      return;
146	    }
147	    result.match(
148	      (failure) {
149	        // Review finding (round 2): mirrors the success branch's own
150	        // `_pendingWrites` overlay below — a write already pending/failed
151	        // when the first page fails to load must still show its own
152	        // placeholder card, not disappear behind a plain error screen
153	        // until the next unrelated `pendingWrites` emission.
154	        if (_pendingWrites.isEmpty) {
155	          emit(MeusRegistrosError(message: failure.message));
156	          return;
157	        }
158	        emit(
159	          MeusRegistrosLoaded(
160	            entries: const [],
161	            nextCursor: null,
162	            pendingWrites: _pendingWrites,
163	          ),
164	        );
165	      },
166	      (page) {
167	        // Same degenerate-cursor distrust as `_fetchMore`'s own guard below:
168	        // a page reporting zero items is treated as exhausted regardless of
169	        // `page.nextCursor` — an empty first page with a non-null cursor
170	        // would otherwise strand the user on `MeusRegistrosEmpty` with no
171	        // way back to a cursor this state no longer tracks. Forced
172	        // unconditionally (Review finding, round 1): independent of
173	        // `_pendingWrites` below — a pending write outstanding over an
174	        // otherwise-empty first page must still null out the cursor, not
175	        // just skip the `MeusRegistrosEmpty` branch beneath it.
176	        final nextCursor = page.items.isEmpty ? null : page.nextCursor;
177	        // spec-4-2: a pending write already outstanding still needs its
178	        // own placeholder card to show, even over an otherwise-empty first
179	        // page — skips straight to `MeusRegistrosEmpty` only once neither
180	        // applies.
181	        if (page.items.isEmpty && _pendingWrites.isEmpty) {
182	          emit(const MeusRegistrosEmpty());
183	          return;
184	        }
185	        emit(
186	          MeusRegistrosLoaded(
187	            entries: dedupedById(page.items, (entry) => entry.id),
188	            nextCursor: nextCursor,
189	            pendingWrites: _pendingWrites,
190	          ),
191	        );
192	      },
193	    );
194	  }
195	
196	  /// `MeusRegistrosScreen`'s scroll listener calls this near the list's
197	  /// end. A no-op while not [MeusRegistrosLoaded], while
198	  /// [MeusRegistrosLoaded.nextCursor] is already `null`, while a call is
199	  /// already in flight, or — critically — once
200	  /// [MeusRegistrosLoaded.loadMoreFailed] is already `true`: without that
201	  /// last guard, a failed page's own footer swapping from a spinner to a
202	  /// "Tentar novamente" button can shift the list's `maxScrollExtent`
203	  /// just enough to leave the scroll position still inside the
204	  /// pre-fetch-buffer zone, re-firing this same listener and retrying
205	  /// forever — observed directly as an unbounded `pumpAndSettle` loop in
206	  /// this screen's own widget test. Once failed, only an explicit
207	  /// [retryLoadMore] (the footer's own button) tries again.
208	  Future<void> loadMore() => _fetchMore(isRetry: false);
209	
210	  /// The footer's "Tentar novamente" button — the one path allowed to
211	  /// retry past a [MeusRegistrosLoaded.loadMoreFailed] of `true`
212	  /// ([loadMore]'s own doc).
213	  Future<void> retryLoadMore() => _fetchMore(isRetry: true);
214	
215	  Future<void> _fetchMore({required bool isRetry}) async {
216	    final current = state;
217	    if (current is! MeusRegistrosLoaded ||
218	        current.nextCursor == null ||
219	        current.isLoadingMore ||
220	        (current.loadMoreFailed && !isRetry)) {
221	      return;
222	    }
223	    final generation = _generation;
224	    emit(current.copyWith(isLoadingMore: true, loadMoreFailed: false));
225	    final result = await _repository.list(cursor: current.nextCursor);
226	    if (isClosed || generation != _generation) {
227	      return;
228	    }
229	    // Re-reads `state` rather than closing over `current` — defensive
230	    // against `loadFirstPage()` having reset the state to something other
231	    // than `MeusRegistrosLoaded` while this await was pending.
232	    final latest = state;
233	    if (latest is! MeusRegistrosLoaded) {
234	      return;
235	    }
236	    result.match(
237	      (failure) =>
238	          emit(latest.copyWith(isLoadingMore: false, loadMoreFailed: true)),
239	      (page) {
240	        // I/O matrix: "Next page appended, no dup ids" — defensive
241	        // de-duplication in case a cursor-boundary entry is ever repeated
242	        // by the server, including a repeat *within* this same page
243	        // (`dedupedById`'s running `seenIds` set covers both).
244	        final seenIds = latest.entries.map((entry) => entry.id).toSet();
245	        final newEntries = dedupedById(
246	          page.items,
247	          (entry) => entry.id,
248	          seenIds: seenIds,
249	        );
250	        // Defensive guard against a degenerate server response: if every
251	        // item in this "successful" page was already present by id (zero
252	        // genuinely-new entries) yet the server still reports a non-null
253	        // `nextCursor`, treat the page as exhausted rather than trusting
254	        // that cursor — otherwise a misbehaving/stuck server cursor could
255	        // make the scroll listener keep re-triggering `loadMore()`
256	        // indefinitely with no progress.
257	        final nextCursor = newEntries.isEmpty ? null : page.nextCursor;
258	        emit(
259	          MeusRegistrosLoaded(
260	            entries: [...latest.entries, ...newEntries],
261	            nextCursor: nextCursor,
262	            pendingWrites: latest.pendingWrites,
263	          ),
264	        );
265	      },
266	    );
267	  }
268	
269	  @override
270	  Future<void> close() async {
271	    await _pendingSubscription.cancel();
272	    await _confirmedSubscription.cancel();
273	    return super.close();
274	  }
275	}
