9	/// Drives `EntriesSearchBar`/`MeusRegistrosScreen`'s docked search surface
10	/// (spec-5-1) — the first real `Resource<T>` consumer (AD-12: "single data
11	/// source, single fetch" is exactly this screen's search slice, unlike
12	/// `MeusRegistrosState`'s own paginated shape). A DI `lazySingleton`
13	/// (Code Map), mirroring `MeusRegistrosCubit`: long-lived, so a query
14	/// already typed survives leaving and re-entering `/meus-registros` within
15	/// the same app session — though [onQueryChanged] is never called except
16	/// by the live `EntriesSearchBar`'s own `onChanged`, there is no
17	/// "re-run the last query on return" behavior to preserve here beyond the
18	/// cubit simply outliving the screen like `MeusRegistrosCubit` already
19	/// does.
20	class EntriesSearchCubit extends Cubit<Resource<List<Entry>>> {
21	  EntriesSearchCubit(this._repository) : super(const ResourceIdle());
22	
23	  final EntriesRepository _repository;
24	
25	  /// `EntriesSearchBar`'s own debounce window (I/O matrix: "5 keystrokes
26	  /// within 300ms -> exactly one `entries-search` call fires, for the
27	  /// final value").
28	  static const _debounceDuration = Duration(milliseconds: 300);
29	
30	  Timer? _debounceTimer;
31	
32	  /// A monotonic counter guarding against a stale in-flight [search] call's
33	  /// result landing after a newer one has already changed the state —
34	  /// mirrors `MeusRegistrosCubit._generation` exactly. Bumped both when a
35	  /// new debounced search actually starts *and* when the query is cleared
36	  /// back to idle (Boundaries' "Stale response" row: an in-flight query A
37	  /// must never land once query B — even an empty one — has already
38	  /// superseded it).
39	  int _generation = 0;
40	
41	  /// `EntriesSearchBar.onChanged`'s one call site — [raw] is the text
42	  /// field's current (untrimmed) value on every keystroke. Cancels any
43	  /// pending debounce `Timer` first, regardless of outcome below (Code
44	  /// Map/Boundaries): a keystroke always supersedes whatever this cubit
45	  /// was about to do next.
46	  void onQueryChanged(String raw) {
47	    _debounceTimer?.cancel();
48	    final query = raw.trim();
49	    if (query.isEmpty) {
50	      // I/O matrix: "Query cleared" — no request, pending work discarded,
51	      // timeline shown. Bumping the generation here (not only inside
52	      // [_search]) is what actually discards an already-in-flight
53	      // previous query's result once it resolves.
54	      _generation++;
55	      // Review finding: `close()` can race this synchronous call too (a
56	      // fast app teardown landing between a keystroke and this handler) —
57	      // same `isClosed` rationale `_search`'s own guard below already
58	      // documents; `emit()` after `close()` would otherwise throw.
59	      if (isClosed) {
60	        return;
61	      }
62	      emit(const ResourceIdle());
63	      return;
64	    }
65	    _debounceTimer = Timer(_debounceDuration, () => _search(query));
66	  }
67	
68	  Future<void> _search(String query) async {
69	    final generation = ++_generation;
70	    // Review finding: deliberately *not* `const` — `ResourceLoading<T>`
71	    // has no custom `==`, so `const ResourceLoading()` is a canonicalized
72	    // singleton instance. Two searches in a row (e.g. "an" still in
73	    // flight when "ans" debounces) would otherwise both emit that exact
74	    // same instance; `Cubit.emit` (package:bloc) skips re-emitting a state
75	    // `==` to the current one, so the second transition into loading
76	    // would silently no-op — `MeusRegistrosScreen._onSearchStateChanged`'s
77	    // listener never re-fires, and its 300ms skeleton timer never resets
78	    // for "ans", measuring RNF01's threshold from the wrong start time. A
79	    // fresh (non-const) instance is identity-distinct from the prior one
80	    // even though both are `ResourceLoading`, so `emit` always proceeds.
81	    emit(ResourceLoading());
82	    final result = await _repository.search(query);
83	    // Mirrors `MeusRegistrosCubit.loadFirstPage`'s own guard: `close()` can
84	    // race this awaited call, and a newer query (or a clear back to idle)
85	    // can have superseded this one while it was in flight.
86	    if (isClosed || generation != _generation) {
87	      return;
88	    }
89	    result.match(
90	      (failure) => emit(ResourceError(failure)),
91	      (entries) => emit(ResourceData(entries)),
92	    );
93	  }
94	
95	  @override
96	  Future<void> close() {
97	    _debounceTimer?.cancel();
98	    return super.close();
99	  }
100	}
