603	/// "Hoje"/"Ontem"/`dd/mm/yyyy` — presentation's own job (Code Map: day
604	/// labels aren't the pure `groupEntriesByDate()`'s concern). [date] is
605	/// always already truncated to local midnight (`EntryDateGroup`'s own
606	/// contract).
607	String _dayLabel(DateTime date) {
608	  final now = DateTime.now();
609	  final today = DateTime(now.year, now.month, now.day);
610	  final yesterday = today.subtract(const Duration(days: 1));
611	  if (date == today) {
612	    return 'Hoje';
613	  }
614	  if (date == yesterday) {
615	    return 'Ontem';
616	  }
617	  final day = date.day.toString().padLeft(2, '0');
618	  final month = date.month.toString().padLeft(2, '0');
619	  return '$day/$month/${date.year}';
620	}
